+fn trailmix_q_width(wq: usize) -> usize {
+    let w = wq.max(1);
+    std::env::var("TRAILMIX_Q_CAP")
+        .ok()
+        .and_then(|s| s.parse::<usize>().ok())
+        .map_or(w, |cap| w.min(cap.max(1)))
+}
