+static TRAILMIX_Q_STEP_CAPS: OnceLock<HashMap<usize, usize>> = OnceLock::new();
+
+fn trailmix_q_step_caps() -> &'static HashMap<usize, usize> {
+    TRAILMIX_Q_STEP_CAPS.get_or_init(|| {
+        let mut out = HashMap::new();
+        let Ok(raw) = std::env::var("TRAILMIX_Q_CAP_STEP_SET") else {
+            return out;
+        };
+        for part in raw.split(',') {
+            let mut fields = part.split(':');
+            let (Some(step), Some(cap)) = (fields.next(), fields.next()) else {
+                continue;
+            };
+            let (Ok(step), Ok(cap)) = (step.parse::<usize>(), cap.parse::<usize>()) else {
+                continue;
+            };
+            out.insert(step, cap.max(1));
+        }
+        out
+    })
+}
