+fn trailmix_q_width_for_step(step: usize, wq: usize) -> usize {
+    let base = trailmix_q_width(wq);
+    trailmix_q_step_caps()
+        .get(&step)
+        .map_or(base, |cap| wq.max(1).min((*cap).max(base)))
+}

